    # all_values = [item['value'] for item in iocs]

    # Process ground truth values to remove square brackets and replace 'hxxp' with 'http'
    gt_values = [item.replace("[", "").replace("]", "").replace("hxxp", "http").replace("hxxps", "https").replace('[.]', '[]') for item in gt_values]
    all_values = [item.replace("[", "").replace("]", "").replace("hxxp", "http").replace("hxxps", "https").replace('[.]', '[]') for item in all_values]

    # Output the processed ground truth list
    print(gt_values)
    print(len(gt_values))
    ground_truth_set = {gt.lower() for gt in gt_values}

    # Count true positives where any part of the predicted string appears in ground truth
    true_positives = sum(
        any(pred.lower() in gt for gt in ground_truth_set)
        for pred in all_values
    )

    # Count false positives (predicted items not considered true positives)
    false_positives = len(all_values) - true_positives

    # Count false negatives (ground truth items not matched by any predicted item)
    false_negatives = sum(
        not any(gt in pred.lower() for pred in all_values)
        for gt in ground_truth_set
    )

    # Calculate precision and recall
    precision = true_positives / (true_positives + false_positives)
    recall = true_positives / (true_positives + false_negatives)

    # Print the results
    print(f"Precision: {precision:.4f}")
    print(f"Recall: {recall:.4f}")


